export default function f({ folder, createdAfter }) {
  if (
    !/^[\w-]+$/.test(folder) ||
    folder.includes("YOUR_") ||
    !/^\d{4}-\d\d-\d\dT\d\d:\d\d:\d\dZ$/.test(createdAfter) ||
    !Number.isFinite(Date.parse(createdAfter))
  )
    throw Error("Configure Drive folder and UTC start time");
  return {
    query:
      "'" + folder + "' in parents and trashed = false and createdTime >= '" + createdAfter + "'",
  };
}

