export default function f({ nextPageToken, files, previous }) {
  const state = previous ?? { page: 0, files: [] };
  if (++state.page > 10000) throw Error("Too many Drive pages");
  state.files.push(...files);
  return { state, done: !nextPageToken, pageToken: nextPageToken ?? null, files: state.files };
}

