export default async function f({ files, previous, pageState, ack, resolution }, ctx) {
  if (!Array.isArray(files)) throw Error("Missing Drive files");
  const page = pageState?.page ?? 0;
  const state = previous?.page === page ? previous : { index: 0, page };
  if (!Number.isInteger(state.index) || state.index < 0) throw Error("Invalid progress");
  while (state.index < files.length) {
    const file = files[state.index++];
    if (!file?.id || !String(file.mimeType ?? "").startsWith("video/")) continue;
    const key = "private-video:" + file.id,
      old = await ctx.state.get(key);
    if (old?.phase === "done") continue;
    if (old?.phase === "uploaded" && old.videoId)
      return {
        state,
        done: false,
        key,
        fileId: file.id,
        name: file.name ?? file.id,
        videoId: old.videoId,
        uploaded: true,
      };
    if (old) {
      if (ack !== key || !["confirmed", "absent"].includes(resolution))
        throw Error("Reconcile " + key);
      if (resolution === "confirmed") {
        await ctx.state.set(key, { ...old, phase: "done" });
        continue;
      }
      await ctx.state.set(key, null);
    }
    await ctx.state.set(key, { phase: "pending", fileId: file.id });
    return {
      state,
      done: false,
      key,
      fileId: file.id,
      name: file.name ?? file.id,
      videoId: "-",
      uploaded: false,
    };
  }
  return { state, done: true, key: "", fileId: "-", name: "", videoId: "-", uploaded: false };
}

