export default function f({ fileId, name }) {
  if (!fileId) throw Error("Missing Drive file");
  const requestId = "drive_" + fileId;
  if (!/^[A-Za-z0-9_-]{16,128}$/.test(requestId)) throw Error("Invalid Drive ID");
  return { requestId, body: { requestId, fileId, title: name } };
}

