export default async function f({ key, fileId, requestId, status, body, previous }, ctx) {
  const state = previous ?? { count: 0 };
  if (++state.count > 120) throw Error("Inspect upload relay status");
  if (status !== 200 || body?.requestId !== requestId) throw Error("Inspect upload relay");
  if (body.status === "pending") return { done: false, videoId: "-", state };
  if (body.status !== "done" || !body.videoId) throw Error("Inspect upload relay");
  const prior = await ctx.state.get(key);
  if (prior?.phase !== "pending" || prior.fileId !== fileId)
    throw Error("Missing upload checkpoint");
  await ctx.state.set(key, { ...prior, phase: "uploaded", videoId: body.videoId });
  return { done: true, videoId: body.videoId, state };
}

