export default function f({ body, videoId }) {
  const text = String(body ?? "")
    .replace(/^\uFEFF/, "")
    .replace(/\r\n?/g, "\n");
  const lines = text
    .split("\n")
    .filter(
      (line) =>
        line.trim() &&
        !/^WEBVTT(?:\s|$)/.test(line) &&
        !/^\d+$/.test(line.trim()) &&
        !/-->/.test(line) &&
        !/^NOTE(?:\s|$)/.test(line),
    );
  const transcript = lines
    .join(" ")
    .replace(/<[^>]*>/g, "")
    .replace(/&amp;/g, "&")
    .replace(/&lt;/g, "<")
    .replace(/&gt;/g, ">")
    .replace(/\s+/g, " ")
    .trim();
  if (!videoId || !transcript) throw Error("No usable caption for this video");
  return {
    prompt: `Return only JSON with title (max 100 characters), description in first person, and tags (array). Write a detailed concise YouTube description with 2-4 emoji and 2-5 hashtags based strictly on this transcript.\n\n${transcript}`,
  };
}

