export default async function f({ key, fileId, videoId, video, deleteSource }, ctx) {
  if (!videoId || video?.id !== videoId) throw Error("Inspect YouTube metadata update");
  const s = await ctx.state.get(key);
  if (s?.phase !== "uploaded" || s.fileId !== fileId || s.videoId !== videoId)
    throw Error("Missing video association");
  await ctx.state.set(key, { ...s, phase: deleteSource ? "delete_pending" : "done" });
  return { remove: deleteSource };
}

