export default async function f({ key, fileId, deleted, deletedId }, ctx) {
  const s = await ctx.state.get(key);
  if (!deleted || deletedId !== fileId || s?.phase !== "delete_pending" || s.fileId !== fileId)
    throw Error("Inspect source deletion");
  await ctx.state.set(key, { ...s, phase: "done" });
  return { ok: true };
}
